import 'package:flutter/material.dart';import 'app_Controlers/darktheme.dart';import 'Screens/titleScreen.dart';import 'Screens/nameScreen.dart';void main() {  runApp(const MyApp());}class MyApp extends StatefulWidget {  const MyApp({Key? key}) : super(key: key);  @override  State<MyApp> createState() => _MyAppState();}class _MyAppState extends State<MyApp> {  bool isDarkTheme = false;  void toggleTheme() {    setState(() {      isDarkTheme = !isDarkTheme;    });  }  @override  Widget build(BuildContext context) {    return ThemeProvider(      isDarkTheme: isDarkTheme,      toggleTheme: toggleTheme,      child: MaterialApp(          debugShowCheckedModeBanner: false,          theme: isDarkTheme ? ThemeData.dark() : ThemeData.light(),          routes: {            //navegação: é aqui que voce adiciona para os botoes nevegarem para as proximas paginas.            '/': (context) => TitleScreen(),            '/name': (context) => NameScreen(),          }),    );  }}